from pathlib import Path
P=Path(__file__).parent/'dist'
f=P/'field.html';s=f.read_text()
def shot(label,device='Phone',shape='phone'):
 return f'''<figure class="field-shot {shape}"><div class="field-shot-space"><span class="field-shot-label">{device.upper()} SCREENSHOT SPACE</span><span class="field-shot-glyph" aria-hidden="true">▣</span><strong>{label}</strong><small>Add your ArcHorizon capture here</small></div><figcaption>Suggested capture: {label.lower()}.</figcaption></figure>'''

main=f'''<main class="field-page"><section class="field-hero"><div class="wrap field-hero-grid"><div><div class="breadcrumb"><a href="index.html">Overview</a> / <a href="features.html">Features</a> / Companion Field App</div><span class="eyebrow">The team’s side of the incident</span><h1>The assignment in hand. The field in the picture.</h1><p>The ArcHorizon companion app gives assigned personnel the details they need to work, a map for context, and a fast way to report status and findings. Updates return to the same incident record used by command and planning.</p><div class="field-hero-links"><a href="#assignment-home">Explore the field screen ↓</a><a href="#field-to-command">How updates move →</a></div></div>{shot('Team assignment home with narrative feed and actions','Phone','phone hero-phone')}</div></section><section class="section" id="assignment-home"><div class="wrap field-home-layout"><div><span class="eyebrow">The working screen</span><h2>Start with the assignment, then stay with the narrative.</h2><p class="lead">The home view centers the team’s current assignment. A compact header shows task details and a single location field; the narrative feed gives the team a running account of what has happened.</p><div class="field-home-details"><article><b>At the top</b><span>Current task, team context, and location.</span></article><article><b>In the center</b><span>Assignment and narrative updates in the order the team needs them.</span></article><article><b>Within reach</b><span>Status controls followed by actions for intel, narrative, messaging, and hazards.</span></article></div></div>{shot('Assignment and narrative home screen','Phone','phone')}</div></section><section class="section alt"><div class="wrap"><div class="section-head"><span class="eyebrow">Know the work</span><h2>Task details and map context travel together.</h2><p class="lead">A team can open the full assignment for objectives, timing, supervisor, hazards, and additional instructions. The map keeps the assigned area, access, and related features close to that description.</p></div><div class="field-pair"><div>{shot('Task details with assignment objective and instructions','Phone','phone')}<h3>Task detail</h3><p>The fuller task record is available when the short home summary is not enough.</p></div><div>{shot('Field map showing assignment area and operational features','Phone','phone')}<h3>Map</h3><p>Geometry and operational features carry through from the desktop planning and GIS workspaces.</p></div></div><div class="field-detail-link"><a class="text-link" href="tasks.html">How Operations creates an assignment →</a><a class="text-link" href="mapping.html">How GIS supplies the geography →</a></div></div></section><section class="section field-status"><div class="wrap field-status-grid"><div><span class="eyebrow">Status and check-in</span><h2>Update the team’s position in the operation.</h2><p class="lead">Status controls are available on the working screen, so the team can report movement and availability without leaving the assignment. Check-in and status are reflected in Operations.</p><div class="field-status-examples"><div><strong>Briefed / en route</strong><span>The team has its instructions and is moving toward the work.</span></div><div><strong>Arrived / working</strong><span>Operations can see that the team reached its area and started the task.</span></div><div><strong>Returning / available</strong><span>The resource comes back into the picture for debriefing or reassignment.</span></div></div><p class="field-status-note">Team status describes the resource. Task status describes progress on the assignment. Both remain visible to staff.</p></div>{shot('Status controls and check-in on the team screen','Phone','phone')}</div></section><section class="section alt field-reporting"><div class="wrap"><div class="section-head"><span class="eyebrow">Field reporting</span><h2>Capture the detail while it is still fresh.</h2><p class="lead">The app places reporting actions after the live narrative so a team can document an observation at the point of work and keep the context attached to its task.</p></div><div class="field-report-grid"><article><span>01 / NARRATIVE</span><h3>Record the sequence</h3><p>Add a tasking, safety, critical, or general entry to the incident narrative. The category helps readers find the type of update without adding a significance scale.</p></article><article><span>02 / INTEL</span><h3>Send a finding</h3><p>Report a clue or observation with its location and context for intelligence review and possible follow-up.</p></article><article><span>03 / HAZARDS</span><h3>Flag a condition</h3><p>Identify a hazard that affects the team or the next assignment, and carry its location into the operational picture.</p></article><article><span>04 / MESSAGING</span><h3>Coordinate directly</h3><p>Exchange assignment-related information with the people coordinating the work.</p></article></div><div class="field-report-shots">{shot('Add narrative entry with category and text','Phone','phone')}{shot('Field intel or hazard report form','Phone','phone')}</div></div></section><section class="section field-flow" id="field-to-command"><div class="wrap"><span class="eyebrow">One record across devices</span><h2>What the team sends changes what staff can see.</h2><p class="lead">The field app is a focused part of ArcHorizon. It uses the task and map prepared on desktop, then returns status and observations to the modules that need them.</p><div class="field-flow-list"><div><a href="operations.html"><b>Operations</b></a><span>Assigns the team and receives check-in, status, and task progress.</span></div><div><a href="intelligence.html"><b>Intelligence</b></a><span>Receives clues and observations for review, leads, and follow-up.</span></div><div><a href="medical-safety.html"><b>Safety &amp; GIS</b></a><span>See hazards in the assignment and on the map.</span></div><div><a href="documentation.html"><b>Incident record</b></a><span>Retains the narrative and activity that support reports and debriefings.</span></div><div><a href="command.html"><b>Command &amp; planning</b></a><span>Use the changing picture to adjust priorities and the next assignment.</span></div></div></div></section><section class="section alt field-modes"><div class="wrap field-modes-grid"><div><span class="eyebrow">More than one operating context</span><h2>Search response and planned events use the same foundation.</h2><p class="lead">The companion app adapts the field view to the incident type. A search team needs its area and task details; a planned event team may need schedule and position information in the same assignment framework.</p><ul class="ops-checks"><li>Show the details that matter to the current event or response.</li><li>Keep team status and field narrative in the shared record.</li><li>Use the same desktop coordination path for both types of work.</li></ul></div>{shot('Planned event team home with schedule and assignment','Phone','phone')}</div></section><section class="section field-tablet"><div class="wrap"><div class="section-head"><span class="eyebrow">Field hardware</span><h2>Room to work on a tablet.</h2><p class="lead">The landscape tablet view uses the additional space for an MDT-style layout: assignment, narrative, map, and actions can be read together without turning the field screen into a desktop command console.</p></div>{shot('Landscape tablet MDT view with task, feed, and map','Landscape tablet','tablet')}</div></section><section class="section dark"><div class="wrap"><span class="eyebrow">Focused access</span><h2>Give each person the right view.</h2><p class="lead">Field users work primarily within their team assignment. Incident members have the write actions needed for that role; external participants can be given a view-only picture. The desktop retains the broader command and administrative tools.</p><div class="related"><a href="tasks.html">Tasks &amp; assignments →</a><a href="status-boards.html">Status boards →</a><a href="situational-awareness.html">Shared incident picture →</a></div></div></section></main>'''
start=s.index('<main>');end=s.index('</main>',start)+len('</main>');s=s[:start]+main+s[end:]
s=s.replace('<meta name="description" content="Assignments, maps, status, and field reporting on mobile.">','<meta name="description" content="Explore the ArcHorizon companion field app: assignments, maps, status and check-in, narrative, intel, hazards, messaging, and landscape tablet use.">')
f.write_text(s)
css='''
/* Companion field app: a field-centered page with phone and tablet screenshot spaces. */
.field-hero{background:linear-gradient(118deg,#071c30 7%,#0c2f4a 68%,#2e5672);color:#fff;padding:65px 0 74px;border-bottom:4px solid var(--orange)}.field-hero-grid{display:grid;grid-template-columns:1.15fr .85fr;gap:65px;align-items:center}.field-hero .breadcrumb{color:#b6d0de}.field-hero .eyebrow{color:#ffad61}.field-hero h1{max-width:730px}.field-hero p{font-size:1.18rem;color:#d7e7ed;max-width:690px}.field-hero-links{display:flex;flex-wrap:wrap;gap:14px 28px;margin-top:25px}.field-hero-links a{color:#ffb870;font-weight:750;text-underline-offset:4px}.field-shot{margin:0}.field-shot-space{display:flex;flex-direction:column;justify-content:center;align-items:center;gap:12px;text-align:center;margin:auto;padding:28px;background:linear-gradient(145deg,#e9f0f4,#f8fafb);border:2px dashed #86a3b3;color:#25495b}.field-shot.phone .field-shot-space{width:min(100%,330px);aspect-ratio:10/17;min-height:390px;border-radius:20px}.field-shot.tablet .field-shot-space{width:min(100%,1020px);aspect-ratio:16/9;min-height:300px;border-radius:13px}.field-hero .field-shot-space{background:linear-gradient(145deg,#143b55,#1d4b65);color:#f0f7fa;border-color:#87a8ba}.field-shot-label{color:#a9570a;font-size:.72rem;font-weight:800;letter-spacing:.15em}.field-hero .field-shot-label{color:#ffb66d}.field-shot-glyph{font-size:2.6rem;opacity:.65;line-height:1}.field-shot-space strong{font:700 1.18rem 'Exo 2',sans-serif;max-width:240px}.field-shot-space small{font-size:.82rem;opacity:.76}.field-shot figcaption{font-size:.86rem;color:var(--muted);padding:9px 0;text-align:center}.field-hero .field-shot figcaption{color:#cfdee7}.field-home-layout,.field-status-grid,.field-modes-grid{display:grid;grid-template-columns:1.1fr .9fr;gap:65px;align-items:center}.field-home-details{border-top:3px solid var(--orange);margin-top:27px}.field-home-details article{display:grid;grid-template-columns:125px 1fr;gap:16px;padding:15px 0;border-bottom:1px solid var(--line)}.field-home-details span{color:var(--muted)}.field-pair{display:grid;grid-template-columns:1fr 1fr;gap:45px}.field-pair>div{text-align:center}.field-pair h3{margin:18px 0 9px}.field-pair p{max-width:370px;margin:auto;color:var(--muted)}.field-detail-link{display:flex;flex-wrap:wrap;gap:12px 26px;margin-top:36px}.field-status{background:#e9f1f5}.field-status-examples{border-top:3px solid var(--orange);margin:28px 0}.field-status-examples>div{padding:13px 0;border-bottom:1px solid var(--line)}.field-status-examples strong,.field-status-examples span{display:block}.field-status-examples span{color:var(--muted)}.field-status-note{font-size:.92rem;color:var(--muted)}.field-report-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.field-report-grid article{background:#fff;border:1px solid var(--line);border-top:4px solid var(--steel);padding:24px}.field-report-grid span{font-size:.74rem;color:#a9570a;letter-spacing:.12em;font-weight:800}.field-report-grid h3{margin-top:24px}.field-report-grid p{color:var(--muted)}.field-report-shots{display:grid;grid-template-columns:1fr 1fr;gap:26px;margin-top:42px}.field-flow{background:#0b2740;color:#fff}.field-flow .eyebrow{color:#ffad61}.field-flow .lead{color:#d1e2e9}.field-flow-list{margin-top:34px;display:grid;grid-template-columns:repeat(5,1fr);gap:12px}.field-flow-list>div{border-top:3px solid var(--orange);background:#173e5a;padding:20px}.field-flow-list a{color:#ffb76f}.field-flow-list b{display:block;font:700 1.08rem 'Exo 2',sans-serif;margin-bottom:12px}.field-flow-list span{color:#d6e7ed;font-size:.91rem}.field-tablet .field-shot-space strong{max-width:440px}body[data-theme="dark"] .field-status{background:#102f47}body[data-theme="dark"] .field-shot-space{background:linear-gradient(145deg,#163950,#20485f);border-color:#769cb2;color:#e7f1f5}body[data-theme="dark"] .field-hero .field-shot-space{background:linear-gradient(145deg,#143b55,#1d4b65)}body[data-theme="dark"] .field-report-grid article{background:#173a52;border-color:#3e6076}body[data-theme="dark"] .field-shot-label,body[data-theme="dark"] .field-report-grid span{color:#ffb76f}@media(max-width:1100px){.field-flow-list{grid-template-columns:repeat(3,1fr)}.field-report-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:850px){.field-hero-grid,.field-home-layout,.field-status-grid,.field-modes-grid{grid-template-columns:1fr;gap:40px}.field-hero .field-shot.phone .field-shot-space{width:min(100%,320px)}.field-pair{gap:25px}}@media(max-width:640px){.field-hero{padding:50px 0 60px}.field-pair,.field-report-shots,.field-report-grid,.field-flow-list{grid-template-columns:1fr}.field-home-details article{grid-template-columns:1fr;gap:4px}.field-shot.tablet .field-shot-space{min-height:210px}.field-flow-list>div{padding:18px}}
'''
with (P/'styles.css').open('a') as out:out.write(css)
gen=Path(__file__).parent/'generate_sections.py';t=gen.read_text();t=t.replace("'situational-awareness.html'}:","'situational-awareness.html','field.html'}:")
gen.write_text(t)
